for(const b of document.querySelectorAll('.close-panel'))b.addEventListener('click',closePanel);$('scrim').addEventListener('click',closePanel);
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&!picker.active&&!campaignView?.active){closePanel();game.placement=null;updatePlacement();}if(e.key==='Tab'&&modal){const all=Array.from($(modal).querySelectorAll('button,input,select')).filter(e=>!e.disabled&&!e.hidden&&e.offsetParent);const i=all.indexOf(document.activeElement);if(e.shiftKey&&i<=0){e.preventDefault();all.at(-1)?.focus();}else if(!e.shiftKey&&i===all.length-1){e.preventDefault();all[0]?.focus();}}});
